parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "isSupportQuestion": {
      "type": "boolean",
      "description": "Whether the email is a customer support question about returns, repairs, warranties, exchanges, shipping, billing, gift cards, privacy, or store policy (case a)."
    },
    "shouldReply": {
      "type": "boolean",
      "description": "Whether a draft reply should be created at all. True for genuine support questions (case a) and genuine misdirected inquiries that expect a human reply (case b). False for spam, newsletters, marketing, or automated notifications that don't need a reply (case c)."
    },
    "category": {
      "type": "string",
      "enum": ["returns", "repairs", "warranty", "exchanges", "billing", "shipping", "privacy", "misdirected", "other"]
    },
    "draftReply": {
      "type": "string",
      "description": "The drafted reply text - the policy-grounded support answer for case (a), or the polite redirect message for case (b). Empty string if shouldReply is false."
    },
    "confidenceRating": {
      "type": "string",
      "enum": ["strong", "medium", "low"],
      "description": "How well the retrieved policy documentation supports this answer. 'strong' = search_store_policies returned specific info (timelines, fees, eligibility, etc.) that directly and fully answers the question. 'medium' = it returned relevant policy info but only general or partial coverage of the specific situation, requiring some interpretation. 'low' = no matching policy was found and the reply uses the human-escalation phrasing, or the email is a misdirected inquiry (case b), or shouldReply is false."
    }
  },
  "required": ["isSupportQuestion", "shouldReply", "category", "draftReply", "confidenceRating"]
}

parameters.message:
={{ $json.output.draftReply }}

Warmly,
The Gadgets & More Electronics Support Team

